1711	    double py;
1712	    double ex;
1713	    double ey;
1714	
1715	    if (len2 < 1e-6) {
1716	        ex = bx - ax;
1717	        ey = by - ay;
1718	        return ex * ex + ey * ey;
1719	    }
1720	
1721	    t = ((bx - ax) * dx + (by - ay) * dy) / len2;
1722	    if (t < 0.0) {
1723	        t = 0.0;
1724	    } else if (t > 1.0) {
1725	        t = 1.0;
1726	    }
1727	
1728	    px = ax + t * dx;
1729	    py = ay + t * dy;
1730	    ex = bx - px;
1731	    ey = by - py;
1732	    return ex * ex + ey * ey;
1733	}
