1735	/**
1736	 * @brief Douglas-Peucker 简化折线。
1737	 * @param pts 点数组。
1738	 * @param n 点数。
1739	 */
1740	int32_t vmap_render_simplify_polyline(vmap_point_t * pts, int32_t n,
1741	    float min_seg_px, float max_dev_px)
1742	{
1743	    const double min_seg2 = (double)min_seg_px * (double)min_seg_px;
1744	    const double max_dev2 = (double)max_dev_px * (double)max_dev_px;
1745	    int32_t w;
1746	
1747	    if (n < 3) {
1748	        return n;
1749	    }
1750	
1751	    w = 1;
1752	    for (int32_t i = 1; i < n - 1; i++) {
1753	        const double dev2 = pt_seg_dist2((double)pts[w - 1].x, (double)pts[w - 1].y,
1754	            (double)pts[i].x, (double)pts[i].y,
1755	            (double)pts[i + 1].x, (double)pts[i + 1].y);
1756	        const double dx = (double)pts[i].x - (double)pts[w - 1].x;
1757	        const double dy = (double)pts[i].y - (double)pts[w - 1].y;
1758	        const double seg2 = dx * dx + dy * dy;
1759	
1760	        if (dev2 < max_dev2) {
1761	            continue;
1762	        }
1763	
1764	        if (seg2 < min_seg2) {
1765	            pts[w - 1] = pts[i];
1766	        } else {
1767	            pts[w++] = pts[i];
1768	        }
1769	    }
1770	
1771	    {
1772	        const double dx = (double)pts[n - 1].x - (double)pts[w - 1].x;
1773	        const double dy = (double)pts[n - 1].y - (double)pts[w - 1].y;
1774	
1775	        if (dx * dx + dy * dy < min_seg2 && w >= 2) {
1776	            pts[w - 1] = pts[n - 1];
1777	        } else {
1778	            pts[w++] = pts[n - 1];
1779	        }
1780	    }
1781	
1782	    return w;
1783	}
