1840	static void draw_road_polyline(vmap_canvas_t * c, const vmap_point_t * pts,
1841	    int32_t n, int32_t width, uint16_t color)
1842	{
1843	    const int32_t join_r = (width + 1) / 2;
1844	    int32_t i;
1845	
1846	    if (!c || n < 2 || width < 1) {
1847	        return;
1848	    }
1849	
1850	    if (road_ring_is_area(pts, n)) {
1851	        return;
1852	    }
1853	
1854	    /* 早退：点已经是画布坐标，包围盒几乎免费。 */
1855	    {
1856	        int32_t bx1 = pts[0].x;
1857	        int32_t by1 = pts[0].y;
1858	        int32_t bx2 = pts[0].x;
1859	        int32_t by2 = pts[0].y;
1860	
1861	        for (i = 1; i < n; i++) {
1862	            if (pts[i].x < bx1) { bx1 = pts[i].x; }
1863	            if (pts[i].x > bx2) { bx2 = pts[i].x; }
1864	            if (pts[i].y < by1) { by1 = pts[i].y; }
1865	            if (pts[i].y > by2) { by2 = pts[i].y; }
1866	        }
1867	        if (!box_may_write(c, bx1 - join_r - 2, by1 - join_r - 2,
1868	                bx2 + join_r + 2, by2 + join_r + 2)) {
1869	            return;
1870	        }
1871	    }
1872	
1873	    vmap_render_stroke_ribbon(c, pts, n, width, color);
1874	
1875	    for (i = 0; i < n; i++) {
1876	        vmap_render_fill_disc(c, pts[i].x, pts[i].y, join_r, color);
1877	    }
1878	}
