1880	static void draw_road_feature_line(vmap_canvas_t * c, const vmap_feature_t * f,
1881	    float base_x, float base_y, float u, int32_t width, uint16_t color,
1882	    vmap_point_t * scratch, int scratch_cap)
1883	{
1884	    int32_t n;
1885	    int32_t i;
1886	
1887	    if (!f || f->point_count < 2 || width < 1 || !scratch || scratch_cap < 2) {
1888	        return;
1889	    }
1890	
1891	    n = f->point_count;
1892	    if (n > scratch_cap) {
1893	        n = scratch_cap;
1894	    }
1895	
1896	    for (i = 0; i < n; i++) {
1897	        scratch[i].x = (int32_t)lroundf(base_x + vmap_feature_x(f, (uint16_t)i) * u);
1898	        scratch[i].y = (int32_t)lroundf(base_y + vmap_feature_y(f, (uint16_t)i) * u);
1899	    }
1900	
1901	    /* 早退：完全写不到就不必简化、不必描边、不必点圆盘。外扩 = 描边半宽 + AA 余量
1902	     * （保守方向），且必须在 VMAP_ROAD_SIMPLIFY 之前 —— 那一步也是纯浪费。 */
1903	    {
1904	        const int32_t pad = (width + 1) / 2 + 2;
1905	        int32_t bx1 = scratch[0].x;
1906	        int32_t by1 = scratch[0].y;
1907	        int32_t bx2 = scratch[0].x;
1908	        int32_t by2 = scratch[0].y;
1909	
1910	        for (i = 1; i < n; i++) {
1911	            if (scratch[i].x < bx1) { bx1 = scratch[i].x; }
1912	            if (scratch[i].x > bx2) { bx2 = scratch[i].x; }
1913	            if (scratch[i].y < by1) { by1 = scratch[i].y; }
1914	            if (scratch[i].y > by2) { by2 = scratch[i].y; }
1915	        }
1916	        if (!box_may_write(c, bx1 - pad, by1 - pad, bx2 + pad, by2 + pad)) {
1917	            return;
1918	        }
1919	    }
1920	
1921	#if VMAP_ROAD_SIMPLIFY
1922	    n = simplify_road_polyline(scratch, n, VMAP_ROAD_MIN_SEG_PX,
1923	        VMAP_ROAD_MAX_DEV_PX);
1924	    if (n >= 4) {
1925	        n = simplify_road_polyline(scratch, n, VMAP_ROAD_MIN_SEG_PX,
1926	            VMAP_ROAD_MAX_DEV_PX);
1927	    }
1928	#endif
1929	
1930	    draw_road_polyline(c, scratch, n, width, color);
1931	}
