2137	        }
2138	        if (n == s_road_ref_cap && scan.remaining > 0) {
2139	            overflow = true;
2140	        }
2141	
2142	        if (!overflow) {
2143	            /* casing：class 顺序与原来一致（PATH → MOTORWAY）。*/
2144	            for (cls = VMAP_ROAD_PATH; cls >= VMAP_ROAD_MOTORWAY; cls--) {
2145	                int i;
