2150	                    vmap_feature_t f;
2151	                    int raw;
2152	                    const vmap_style_road_t * st;
2153	                    int32_t case_w;
2154	
2155	                    raw = rec[0];
2156	                    if (raw < 1 || raw >= ROAD_STYLE_NUM) {
2157	                        raw = VMAP_ROAD_RESIDENTIAL;
2158	                    }
2159	                    if (raw != cls) {
2160	                        continue;
2161	                    }
2162	                    if (!vmap_feature_iter_next(&one, &f)) {
2163	                        continue;
2164	                    }
2165	                    if (f.point_count < 2 || vmap_feature_is_closed(&f)) {
2166	                        continue;
2167	                    }
2168	                    st = road_style_for(raw);
2169	                    case_w = (int32_t)st->w + (int32_t)style->road_case_extra;
2170	                    if (case_w > (int32_t)st->w) {
2171	                        draw_road_feature_line(c, &f, base_x, base_y, u, case_w,
2172	                            case_color, scratch, scratch_cap);
2173	                    }
2174	                }
2175	            }
2176	
2177	            /* fill：同上。*/
2178	            for (cls = VMAP_ROAD_PATH; cls >= VMAP_ROAD_MOTORWAY; cls--) {
2179	                int i;
2180	
2181	                for (i = 0; i < n; i++) {
2182	                    const uint8_t * rec = s_road_refs[i].rec;
2183	                    vmap_feature_iter_t one = { rec, layer_end, 1 };
2184	                    vmap_feature_t f;
2185	                    int raw;
2186	                    const vmap_style_road_t * st;
2187	                    uint16_t color;
