2211	
2212	    /* 回退：未绑定索引、cap<=0 或索引溢出时走原实现（逐 class 全层扫描）。*/
2213	    for (cls = VMAP_ROAD_PATH; cls >= VMAP_ROAD_MOTORWAY; cls--) {
2214	        vmap_feature_iter_t it = vmap_tile_layer_iter(tile, VMAP_LAYER_ROAD);
2215	        vmap_feature_t f;
2216	        while (vmap_feature_iter_next(&it, &f)) {
2217	            int raw;
2218	            const vmap_style_road_t * st;
