359	    const out = { drawn: 0, skipped: 0 };
360	
361	    function tryPlace(it, pad) {
362	      const tw = textWidth(ctx, it.text, it.font);
363	      const th = it.size * 1.1;
364	      if (it.x < -tw || it.x > W + tw || it.y < -th || it.y > H + th) {
365	        out.skipped++;
366	        return false;
367	      }
368	      const box = textBox(it.x, it.y, tw, th, it.ang || 0);
369	      /* 贴边时把文字拉回视口内（和设备的 clamp 一致） */
370	      const dx = box.x0 < 2 ? 2 - box.x0 : (box.x1 > W - 2 ? W - 2 - box.x1 : 0);
371	      const dy = box.y0 < 2 ? 2 - box.y0 : (box.y1 > H - 2 ? H - 2 - box.y1 : 0);
372	      if (dx) { it.x += dx; box.x0 += dx; box.x1 += dx; }
373	      if (dy) { it.y += dy; box.y0 += dy; box.y1 += dy; }
374	      for (const p of placed) {
375	        if (boxesHit(box, p, pad)) {
376	          out.skipped++;
377	          return false;
378	        }
379	      }
380	      placed.push(box);
381	      drawLabel(ctx, it, box);
382	      out.drawn++;
383	      return true;
384	    }
385	
386	    /* 1) 点标注（水名 / 公园名 / 地名）：prio 大的先占位 */
387	    const points = [];
388	    for (const lb of scene.labels || []) {
389	      if (!lb.name) continue;
390	      if (!opts.showLabels) continue;
391	      const kind = lb.kind;
392	      let color = lab.poi;
393	      let font = labelFont(9.5 * size, null, false);
394	      let prio = lb.prio;
395	      if (kind === 2) {
396	        color = lab.water;
397	        font = labelFont(10.5 * size, null, true);
398	        prio += 40;
399	      } else if (kind === 1) {
400	        color = lab.place;
401	        font = labelFont(12.5 * size, "600", false);
402	        prio += 90;
403	      } else if (kind === 3) {
404	        continue;                       /* 路名走 2) 的沿路排版 */
405	      } else {
406	        color = lab.poi;
407	        font = labelFont(9.5 * size, null, false);
408	      }
409	      points.push({
410	        text: lb.name, x: lb.sx, y: lb.sy, ang: 0, prio,
411	        color, font, size: 9.5 * size, halo: lab.halo,
412	        haloW: kind === 1 ? 4 : LABEL_HALO_W,
413	      });
414	    }
415	    points.sort((a, b) => b.prio - a.prio);
416	    for (const it of points) tryPlace(it, 3);
417	
418	    /* 2) 路名：沿路方向、按等级先后。
419	     * 同一个名字只出一次 —— 数据是按瓦片切的，一条路在相邻瓦片里各有一份，
420	     * 不加这条约束就会像旧版一样把"扬子大道"在屏上印四遍。每个名字取
421	     * 离屏幕中心最近的那一份，保证标在看得见的地方。 */
422	    if (!opts.showLabels || !opts.showRoadNames) return out;
423	    const byName = new Map();
424	    for (const f of scene.road || []) {
425	      if (!f.name || !f.spts || f.spts.length < 2) continue;
426	      if (!vmapRoadVisible(f.attr, opts.zoom)) continue;
427	      const font = labelFont((f.attr <= 2 ? 9.5 : 9) * size, null, false);
428	      const tw = textWidth(ctx, f.name, font);
429	      const anchor = bestLabelAnchor(f.spts, tw + 6);
430	      if (!anchor) { out.skipped++; continue; }
431	      const d = Math.hypot(anchor.x - W / 2, anchor.y - H / 2);
432	      const cur = byName.get(f.name);
433	      if (!cur || d < cur.d) {
434	        byName.set(f.name, {
435	          text: f.name, x: anchor.x, y: anchor.y, ang: anchor.ang,
436	          color: lab.road, font, size: 9 * size, halo: lab.halo,
437	          cls: f.attr, d,
438	        });
439	      }
440	    }
441	    const picks = [...byName.values()].sort((a, b) => (a.cls - b.cls) || (a.d - b.d));
442	    for (const it of picks) tryPlace(it, 2);
443	    return out;
444	  }
445	
446	  /**
447	   * 画一整帧。
448	   * @param ctx 2D 上下文（已按 dpr 缩放）
449	   * @param scene {land,forest,water,waterway,road,labels}
450	   * @param opts  {style, zoom, width, height, showLand, showLabels,
451	   *               showRoadNames, widthScale, labelScale, device}
452	   */
453	  function paint(ctx, scene, opts) {
454	    const st = opts.style;
455	    const zoom = opts.zoom;
456	    const ws = (opts.widthScale || 1) * vmapZoomWidthScale(zoom);
457	    /* 壳要比芯厚出"看得见的一圈"：太薄等于没有，太厚会把小路糊死。 */
458	    const caseExtra = Math.max(1.1, 1.9 * Math.min(1.7, ws));
459

459	
460	    ctx.fillStyle = st.bg;
461	    ctx.fillRect(0, 0, opts.width, opts.height);
462	
463	    if (opts.showLand) {
464	      for (const attr of [1, 2, 3, 4, 5]) {
465	        if (!vmapLandVisible(attr, zoom)) continue;
466	        fillPolys(ctx, (scene.land || []).filter((f) => f.attr === attr), st.land[attr]);
467	      }
468	      fillPolys(ctx, scene.forest, st.forest);
469	    }
470	    fillWater(ctx, scene.water, st.water);
471	    strokeLines(ctx, scene.waterway, st.waterway,
472	      Math.max(1, 1.4 * Math.min(1.5, ws)), null);
473	
474	    /* 道路：从低等级到高等级，每条 = 壳 + 芯；高等级后画，路口自然压住低等级。 */
475	    for (let cls = 7; cls >= 1; cls--) {
476	      const rs = st.roads[cls];
477	      if (!rs || !vmapRoadVisible(cls, zoom)) continue;
478	      const feats = (scene.road || []).filter((f) => f.attr === cls);
479	      if (!feats.length) continue;
480	      const w = rs.w * ws;
481	      const dash = cls === 7 && st.pathDash
482	        ? [st.pathDash[0] * ws, st.pathDash[1] * ws] : null;
483	      if (rs.case && w > 1.2) {
484	        strokeLines(ctx, feats, rs.case, w + caseExtra, null);
485	      }
486	      strokeLines(ctx, feats, rs.fill, w, dash);
487	    }
488	
489	    if (opts.showLabels) placeLabels(ctx, scene, opts);
490	  }
491	
492	  return { paint, placeLabels, bestLabelAnchor, textWidth, labelFont };
493	})();
