41	static int32_t label_dist2(int32_t x, int32_t y, int32_t fx, int32_t fy)
42	{
43	    int32_t dx = x - fx;
44	    int32_t dy = y - fy;
45	    return dx * dx + dy * dy;
46	}
47	
48	static int32_t label_dist2_norm(int32_t x, int32_t y, int32_t fx, int32_t fy,
49	    double scale)
50	{
51	    int64_t d2 = label_dist2(x, y, fx, fy);
52	    double s2 = scale * scale;
53	    if (s2 < 0.0625) {
54	        s2 = 0.0625;
55	    }
56	    return (int32_t)((double)d2 / s2);
57	}
