59	static int32_t other_label_score(uint8_t kind, uint8_t prio,
60	    int32_t x, int32_t y, int32_t fx, int32_t fy, double scale)
61	{
62	    int32_t score = (int32_t)prio;
63	    if (kind == VMAP_LABEL_PLACE) {
64	        score += 20;
65	    } else if (kind == VMAP_LABEL_POI) {
66	        score += 5;
67	    } else if (kind == VMAP_LABEL_WATER) {
68	        score -= 50;
69	    }
70	    score -= label_dist2_norm(x, y, fx, fy, scale) / 2000;
71	    return score;
72	}
