100	     * Horizontal names have wide boxes and lose more anchors to canvas bounds
101	     * and collisions. Sample them more densely than the old 0.55× viewport.
102	     */
103	    *spacing_x = (double)view_w * 0.42;
104	    *spacing_y = (double)view_h * 0.42;
105	    if (*spacing_x < (double)VMAP_ROAD_LABEL_SPACING_MIN_X) {
106	        *spacing_x = (double)VMAP_ROAD_LABEL_SPACING_MIN_X;
107	    }
108	    if (*spacing_y < (double)VMAP_ROAD_LABEL_SPACING_MIN_Y) {
