113	static double road_label_arc_spacing(double dx, double dy, double seg_len,
114	    double spacing_x, double spacing_y)
115	{
116	    if (seg_len < 1.0) {
117	        return spacing_x;
118	    }
119	    double nx = fabs(dx) / seg_len;
120	    double ny = fabs(dy) / seg_len;
121	    return nx * spacing_x + ny * spacing_y;
122	}
