124	static void closest_point_on_segment(int32_t x0, int32_t y0, int32_t x1, int32_t y1,
125	    int32_t px, int32_t py, int32_t * out_x, int32_t * out_y)
126	{
127	    double dx = (double)(x1 - x0);
128	    double dy = (double)(y1 - y0);
129	    double len2 = dx * dx + dy * dy;
130	    if (len2 < 1.0) {
131	        *out_x = x0;
132	        *out_y = y0;
133	        return;
134	    }
135	
136	    double t = ((double)(px - x0) * dx + (double)(py - y0) * dy) / len2;
137	    if (t < 0.0) {
138	        t = 0.0;
139	    } else if (t > 1.0) {
140	        t = 1.0;
141	    }
142	
143	    *out_x = (int32_t)lround(x0 + dx * t);
144	    *out_y = (int32_t)lround(y0 + dy * t);
145	}
