152	static uint32_t utf8_char_bytes(const char * s)
153	{
154	    const uint8_t * p = (const uint8_t *)s;
155	    if (!p || *p == 0) {
156	        return 0;
157	    }
158	    if (*p < 0x80) {
159	        return 1;
160	    }
161	    if ((*p & 0xE0) == 0xC0) {
162	        return 2;
163	    }
164	    if ((*p & 0xF0) == 0xE0) {
165	        return 3;
166	    }
167	    if ((*p & 0xF8) == 0xF0) {
168	        return 4;
169	    }
170	    return 1;
171	}
172	
173	static void road_label_layout_text(uint8_t kind, uint8_t road_vertical,
174	    const char * name, char * out, size_t cap)
175	{
176	    size_t w = 0;
177	    const char * p;
178	
179	    if (!out || cap == 0 || !name) {
180	        return;
181	    }
182	
183	    if (kind != VMAP_LABEL_ROAD || !road_vertical) {
184	        lv_strlcpy(out, name, cap);
185	        return;
186	    }
187	
188	    p = name;
189	    while (*p != '\0') {
190	        uint32_t n = utf8_char_bytes(p);
191	        if (n == 0) {
192	            break;
193	        }
194	        if (w > 0) {
195	            if (w + 1 >= cap) {
196	                break;
197	            }
198	            out[w++] = '\n';
199	        }
200	        if (w + n >= cap) {
201	            break;
202	        }
203	        lv_memcpy(out + w, p, n);
204	        w += n;
205	        p += n;
206	    }
207	    out[w] = '\0';
208	}
