210	static lv_coord_t road_label_single_char_width(const char * utf8, const lv_font_t * font)
211	{
212	    char one[8];
213	    uint32_t n = utf8_char_bytes(utf8);
214	    lv_point_t sz;
215	
216	    if (n == 0) {
217	        return lv_font_get_line_height(font);
218	    }
219	    if (n >= sizeof(one)) {
220	        n = (uint32_t)sizeof(one) - 1U;
221	    }
222	    lv_memcpy(one, utf8, n);
223	    one[n] = '\0';
224	
225	    lv_text_get_size(&sz, one, font, 0, 0, LV_COORD_MAX, LV_TEXT_FLAG_NONE);
226	    if (sz.x > 0) {
227	        return sz.x;
228	    }
229	    return lv_font_get_line_height(font);
230	}
