234	{
235	    road_label_layout_text(kind, road_vertical, name, layout_buf, layout_cap);
236	    if (kind == VMAP_LABEL_ROAD && road_vertical) {
237	        lv_coord_t char_w = road_label_single_char_width(layout_buf, font);
238	        lv_text_get_size(sz, layout_buf, font, 0, 0, char_w, LV_TEXT_FLAG_NONE);
239	    } else {
240	        lv_text_get_size(sz, layout_buf, font, 0, 0, LV_COORD_MAX, LV_TEXT_FLAG_NONE);
241	    }
242	}
