255	static bool segment_bbox_hits_vis(int32_t x0, int32_t y0, int32_t x1, int32_t y1,
256	    int32_t vis_x0, int32_t vis_y0, int32_t vis_x1, int32_t vis_y1)
257	{
258	    int32_t smin_x = x0 < x1 ? x0 : x1;
259	    int32_t smax_x = x0 > x1 ? x0 : x1;
260	    int32_t smin_y = y0 < y1 ? y0 : y1;
261	    int32_t smax_y = y0 > y1 ? y0 : y1;
262	    return smax_x >= vis_x0 && smin_x <= vis_x1 && smax_y >= vis_y0 && smin_y <= vis_y1;
263	}
