265	static void copy_label_name(vmap_label_cand_t * c, const char * text, uint8_t len)
266	{
267	    uint8_t n = len < (uint8_t)(sizeof(c->name) - 1) ? len
268	                                                  : (uint8_t)(sizeof(c->name) - 1);
269	    if (n > 0 && text) {
270	        lv_memcpy(c->name, text, n);
271	    }
272	    c->name[n] = '\0';
273	}
