275	static bool label_in_clip(const vmap_label_collector_t * col, int32_t x, int32_t y)
276	{
277	    uint8_t i;
278	
279	    if (!col || col->clip_n == 0) {
280	        return true;
281	    }
282	    for (i = 0; i < col->clip_n; i++) {
283	        if (x >= col->clip_x1[i] && x < col->clip_x2[i]
284	            && y >= col->clip_y1[i] && y < col->clip_y2[i]) {
285	            return true;
286	        }
287	    }
288	    return false;
289	}
