291	static bool push_label(vmap_label_collector_t * col, int32_t sx, int32_t sy,
292	    uint8_t kind, uint8_t prio, uint8_t road_vertical,
293	    const char * text, uint8_t len)
294	{
295	    if (!col || col->count >= col->cap || !text || len == 0) {
296	        return false;
297	    }
298	    if (!label_in_clip(col, sx, sy)) {
299	        return false;
300	    }
301	
302	    vmap_label_cand_t * c = &col->items[col->count];
303	    c->x = sx;
304	    c->y = sy;
305	    c->kind = kind;
306	    c->prio = prio;
307	    c->road_vertical = road_vertical;
308	    copy_label_name(c, text, len);
309	    col->count++;
310	    return true;
311	}
