313	static void collect_point_labels(vmap_label_collector_t * col,
314	    const vmap_tile_t * tile, float base_x, float base_y, float scale)
315	{
316	    int32_t vis_x0, vis_y0, vis_x1, vis_y1;
317	    float u = 256.0f * scale / (float)vmap_tile_extent(tile);
318	    vmap_label_iter_t it = vmap_tile_label_iter(tile);
319	    vmap_label_t lb;
320	
321	    label_pan_canvas_bounds(col->canvas_w, col->canvas_h,
322	        &vis_x0, &vis_y0, &vis_x1, &vis_y1);
323	
324	    while (vmap_label_iter_next(&it, &lb)) {
325	        int32_t sx;
326	        int32_t sy;
327	
328	        if (col->count >= col->cap || lb.kind == VMAP_LABEL_ROAD) {
329	            continue;
330	        }
331	        sx = (int32_t)(base_x + lb.x * u);
332	        sy = (int32_t)(base_y + lb.y * u);
333	        if (sx < vis_x0 || sx > vis_x1 || sy < vis_y0 || sy > vis_y1) {
334	            continue;
335	        }
336	        push_label(col, sx, sy, lb.kind, lb.priority, 0, lb.text, lb.len);
337	    }
338	}
