345	    int32_t near_y;
346	    int32_t near_d2;
347	    int32_t near_seg_dx;
348	    int32_t near_seg_dy;
349	    bool any_visible;
350	    int32_t vis_min_x;
351	    int32_t vis_min_y;
352	    int32_t vis_max_x;
353	    int32_t vis_max_y;
354	    int32_t pan_x0;
355	    int32_t pan_y0;
356	    int32_t pan_x1;
357	    int32_t pan_y1;
358	    int32_t focus_x;
359	    int32_t focus_y;
360	    const char * name_text;
361	    uint8_t name_len;
