363	} road_collect_ctx_t;
364	
365	static int32_t road_name_near_index(const vmap_label_collector_t * col,
366	    const char * name, uint8_t len, int32_t x, int32_t y)
367	{
368	    int32_t i;
369	    int32_t lim;
370	    int32_t lim2;
371	    double spacing_x;
372	    double spacing_y;
373	
374	    if (!col || !name || len == 0) {
375	        return -1;
376	    }
377	
378	    /*
379	     * Keep repeats dense enough that a viewport crossing a long road sees a
380	     * name, while still merging the duplicate anchors emitted by two tiles at
381	     * their seam.
382	     */
383	    road_label_spacing_from_viewport(col->view_w, col->view_h,
384	        &spacing_x, &spacing_y);
385	    lim = (int32_t)lround((spacing_x + spacing_y) * 0.5);
386	    if (lim < 60) {
387	        lim = 60;
388	    }
389	    lim2 = lim * lim;
390	
391	    for (i = 0; i < col->count; i++) {
392	        int32_t dx;
393	        int32_t dy;
394	
395	        if (col->items[i].kind != VMAP_LABEL_ROAD) {
396	            continue;
397	        }
398	        if (strncmp(col->items[i].name, name, (size_t)len) != 0
399	            || col->items[i].name[len] != '\0') {
400	            continue;
401	        }
402	
403	        dx = col->items[i].x - x;
404	        dy = col->items[i].y - y;
405	        if (dx * dx + dy * dy < lim2) {
406	            return i;
407	        }
408	    }
409	    return -1;
410	}
411	
412	static bool road_push_label(road_collect_ctx_t * ctx, int32_t sx, int32_t sy,
413	    int32_t seg_dx, int32_t seg_dy)
414	{
415	    int32_t near_idx;
416	    uint8_t vertical;
417	
418	    if (ctx->placed >= VMAP_ROAD_LABEL_MAX_PER_WAY) {
419	        return false;
420	    }
421	    if (!point_in_rect(sx, sy, ctx->pan_x0, ctx->pan_y0, ctx->pan_x1, ctx->pan_y1)) {
422	        return false;
423	    }
424	    if (!label_in_clip(ctx->col, sx, sy)) {
425	        return false;
426	    }
427	
428	    vertical = ((seg_dy < 0 ? -seg_dy : seg_dy)
429	        > (seg_dx < 0 ? -seg_dx : seg_dx)) ? 1u : 0u;
430	    near_idx = road_name_near_index(ctx->col, ctx->name_text,
431	        ctx->name_len, sx, sy);
432	    if (near_idx >= 0) {
433	        vmap_label_cand_t * old = &ctx->col->items[near_idx];
434	
435	        /*
436	         * Tile order must not decide the winner. Keep the same-name anchor
437	         * nearest the viewport focus, so a seam candidate cannot suppress the
438	         * road name in the visible center.
439	         */
440	        if (label_dist2(sx, sy, ctx->focus_x, ctx->focus_y)
441	            < label_dist2(old->x, old->y, ctx->focus_x, ctx->focus_y)) {
442	            old->x = sx;
443	            old->y = sy;
444	            old->prio = road_prio_from_attr(ctx->road_attr);
445	            old->road_vertical = vertical;
446	        }
447	        return false;
448	    }
449	    if (ctx->col->count >= ctx->col->cap) {
450	        return false;
451	    }
452	
453	    {
454	        vmap_label_cand_t * c = &ctx->col->items[ctx->col->count];
455	        c->x = sx;
456	        c->y = sy;
457	        c->kind = VMAP_LABEL_ROAD;
458	        c->prio = road_prio_from_attr(ctx->road_attr);
459	        c->road_vertical = vertical;
460	        copy_label_name(c, ctx->name_text, ctx->name_len);
461	        ctx->col->count++;
462	    }
463	    ctx->placed++;
464	    ctx->dist_since_label = 0.0;
465	    return true;
466	}
467	
468	static void collect_road_labels(vmap_label_collector_t * col,
469	    const vmap_tile_t * tile, float base_x, float base_y, float scale)
470	{
471	    float u = 256.0f * scale / (float)vmap_tile_extent(tile);
472	    int32_t pan_x0, pan_y0, pan_x1, pan_y1;
473	    int32_t vis_x0, vis_y0, vis_x1, vis_y1;
474	    double spacing_x = 0.0;
475	    double spacing_y = 0.0;
476	    double spacing_avg;
477	    vmap_feature_iter_t it;
478	    vmap_feature_t f;
479	    road_collect_ctx_t ctx;
480	
481	    label_pan_canvas_bounds(col->canvas_w, col->canvas_h,
482	        &pan_x0, &pan_y0, &pan_x1, &pan_y1);
483	    vis_x0 = pan_x0 - VMAP_ROAD_LABEL_VIS_PAD;
484	    vis_y0 = pan_y0 - VMAP_ROAD_LABEL_VIS_PAD;
485	    vis_x1 = pan_x1 + VMAP_ROAD_LABEL_VIS_PAD;
486	    vis_y1 = pan_y1 + VMAP_ROAD_LABEL_VIS_PAD;
487	    road_label_spacing_from_viewport(col->view_w, col->view_h, &spacing_x, &spacing_y);
488	    spacing_avg = (spacing_x + spacing_y) * 0.5;
489	
490	    it = vmap_tile_layer_iter(tile, VMAP_LAYER_ROAD);
491	    while (vmap_feature_iter_next(&it, &f)) {
492	        uint16_t i;
493	
494	        if (col->count >= col->cap || !vmap_feature_has_name(&f) || f.point_count < 2) {
495	            continue;
496	        }
497	
498	        memset(&ctx, 0, sizeof(ctx));
499	        ctx.col = col;
500	        ctx.pan_x0 = pan_x0;
501	        ctx.pan_y0 = pan_y0;
502	        ctx.pan_x1 = pan_x1;
503	        ctx.pan_y1 = pan_y1;
504	        ctx.focus_x = col->focus_x;
505	        ctx.focus_y = col->focus_y;
506	        ctx.name_text = f.name_text;
507	        ctx.name_len = f.name_len;
508	        ctx.road_attr = f.attr;
509	        ctx.dist_since_label = spacing_avg;
510	        ctx.near_d2 = INT32_MAX;
511	        ctx.vis_min_x = INT32_MAX;
512	        ctx.vis_min_y = INT32_MAX;
513	        ctx.vis_max_x = INT32_MIN;
514	        ctx.vis_max_y = INT32_MIN;
515	
516	        for (i = 0; i + 1 < f.point_count; i++) {
517	            int32_t x0 = (int32_t)(base_x + vmap_feature_x(&f, i) * u);
518	            int32_t y0 = (int32_t)(base_y + vmap_feature_y(&f, i) * u);
519	            int32_t x1 = (int32_t)(base_x + vmap_feature_x(&f, i + 1) * u);
520	            int32_t y1 = (int32_t)(base_y + vmap_feature_y(&f, i + 1) * u);
521	            double dx;
522	            double dy;
523	            double seg_len;
524	            double arc_spacing;
525	            double pos;
526	
527	            if (!segment_bbox_hits_vis(x0, y0, x1, y1, vis_x0, vis_y0, vis_x1, vis_y1)) {
528	                continue;
529	            }
530	
531	            ctx.any_visible = true;
532	            {
533	                int32_t smin_x = x0 < x1 ? x0 : x1;
534	                int32_t smax_x = x0 > x1 ? x0 : x1;
535	                int32_t smin_y = y0 < y1 ? y0 : y1;
536	                int32_t smax_y = y0 > y1 ? y0 : y1;
537	                if (smin_x < ctx.vis_min_x) {
538	                    ctx.vis_min_x = smin_x;
539	                }
540	                if (smin_y < ctx.vis_min_y) {
541	                    ctx.vis_min_y = smin_y;
542	                }
543	                if (smax_x > ctx.vis_max_x) {
544	                    ctx.vis_max_x = smax_x;
545	                }
546	                if (smax_y > ctx.vis_max_y) {
547	                    ctx.vis_max_y = smax_y;
548	                }
549	            }
550	
551	            dx = (double)(x1 - x0);
552	            dy = (double)(y1 - y0);
553	            seg_len = sqrt(dx * dx + dy * dy);
554	            if (seg_len < 1.0) {
555	                continue;
556	            }
557	
558	            {
559	                int32_t cx = 0;
560	                int32_t cy = 0;
561	                int32_t cd2;
562	                closest_point_on_segment(x0, y0, x1, y1, ctx.focus_x, ctx.focus_y,
563	                    &cx, &cy);
564	                cd2 = label_dist2(cx, cy, ctx.focus_x, ctx.focus_y);
565	                if (cd2 < ctx.near_d2) {
566	                    ctx.near_d2 = cd2;
567	                    ctx.near_x = cx;
568	                    ctx.near_y = cy;
569	                    ctx.near_seg_dx = (int32_t)dx;
570	                    ctx.near_seg_dy = (int32_t)dy;
571	                }
572	            }
573	
574	            arc_spacing = road_label_arc_spacing(dx, dy, seg_len, spacing_x, spacing_y);
575	            pos = 0.0;
576	            while (pos < seg_len && ctx.placed < VMAP_ROAD_LABEL_MAX_PER_WAY) {
577	                double need = arc_spacing - ctx.dist_since_label;
578	                if (need <= 0.0) {
579	                    need = arc_spacing;
580	                }
581	                if (pos + need > seg_len) {
582	                    ctx.dist_since_label += seg_len - pos;
583	                    break;
584	                }
585	                pos += need;
586	                {
587	                    int32_t sx = (int32_t)lround(x0 + dx * (pos / seg_len));
588	                    int32_t sy = (int32_t)lround(y0 + dy * (pos / seg_len));
589	                    road_push_label(&ctx, sx, sy, (int32_t)dx, (int32_t)dy);
590	                }
591	            }
592	        }
593	
594	        if (!ctx.any_visible) {
595	            continue;
596	        }
597	
598	        if (ctx.near_d2 < INT32_MAX) {
599	            bool dup_near = false;
600	            int32_t base_idx = col->count - ctx.placed;
601	            int32_t k;
602	            for (k = base_idx; k < col->count; k++) {
603	                if (label_dist2(col->items[k].x, col->items[k].y,
604	                        ctx.near_x, ctx.near_y) < 400) {
605	                    dup_near = true;
606	                    break;
607	                }
608	            }
609	            if (!dup_near) {
610	                road_push_label(&ctx, ctx.near_x, ctx.near_y,
611	                    ctx.near_seg_dx, ctx.near_seg_dy);
612	            }
613	        }
614	
615	        if (ctx.placed == 0) {
616	            road_push_label(&ctx,
617	                (ctx.vis_min_x + ctx.vis_max_x) / 2,
618	                (ctx.vis_min_y + ctx.vis_max_y) / 2,
619	                ctx.vis_max_x - ctx.vis_min_x,
620	                ctx.vis_max_y - ctx.vis_min_y);
621	        }
622	    }
623	}
