671	static bool dirty_covers_inclusive(uint8_t n,
672	    const int32_t * x1, const int32_t * y1,
673	    const int32_t * x2, const int32_t * y2,
674	    int32_t bx1, int32_t by1, int32_t bx2, int32_t by2)
675	{
676	    uint8_t i;
677	
678	    for (i = 0; i < n; i++) {
679	        if (x1[i] <= bx1 && y1[i] <= by1
680	            && x2[i] > bx2 && y2[i] > by2) {
681	            return true;
682	        }
683	    }
684	    return false;
685	}
686	
687	static void dirty_include_inclusive(uint8_t cap, uint8_t * n,
688	    int32_t * x1, int32_t * y1, int32_t * x2, int32_t * y2,
689	    int32_t canvas_w, int32_t canvas_h,
690	    int32_t bx1, int32_t by1, int32_t bx2, int32_t by2)
691	{
692	    int32_t dx1 = bx1;
693	    int32_t dy1 = by1;
694	    int32_t dx2 = bx2 + 1;
695	    int32_t dy2 = by2 + 1;
696	    uint8_t i;
697	    uint8_t best;
698	    int32_t best_grow;
699	
700	    if (!n || !x1 || !y1 || !x2 || !y2 || cap == 0) {
701	        return;
702	    }
703	    if (dx1 < 0) {
704	        dx1 = 0;
705	    }
706	    if (dy1 < 0) {
707	        dy1 = 0;
708	    }
709	    if (dx2 > canvas_w) {
710	        dx2 = canvas_w;
711	    }
712	    if (dy2 > canvas_h) {
713	        dy2 = canvas_h;
714	    }
715	    if (dx1 >= dx2 || dy1 >= dy2) {
716	        return;
717	    }
718	    if (dirty_covers_inclusive(*n, x1, y1, x2, y2, bx1, by1, bx2, by2)) {
719	        return;
720	    }
721	    if (*n < cap) {
722	        i = *n;
723	        x1[i] = dx1;
724	        y1[i] = dy1;
725	        x2[i] = dx2;
726	        y2[i] = dy2;
727	        (*n)++;
728	        return;
729	    }
730	
731	    best = 0;
732	    best_grow = INT32_MAX;
733	    for (i = 0; i < *n; i++) {
734	        int32_t ux1 = x1[i] < dx1 ? x1[i] : dx1;
735	        int32_t uy1 = y1[i] < dy1 ? y1[i] : dy1;
736	        int32_t ux2 = x2[i] > dx2 ? x2[i] : dx2;
737	        int32_t uy2 = y2[i] > dy2 ? y2[i] : dy2;
738	        int32_t old_a = (x2[i] - x1[i]) * (y2[i] - y1[i]);
739	        int32_t new_a = (ux2 - ux1) * (uy2 - uy1);
740	        int32_t grow = new_a - old_a;
741	
742	        if (grow < best_grow) {
743	            best_grow = grow;
744	            best = i;
745	        }
746	    }
747	    {
748	        int32_t ux1 = x1[best] < dx1 ? x1[best] : dx1;
749	        int32_t uy1 = y1[best] < dy1 ? y1[best] : dy1;
750	        int32_t ux2 = x2[best] > dx2 ? x2[best] : dx2;
751	        int32_t uy2 = y2[best] > dy2 ? y2[best] : dy2;
752	
753	        x1[best] = ux1;
754	        y1[best] = uy1;
755	        x2[best] = ux2;
756	        y2[best] = uy2;
757	    }
758	}
759	
760	void vmap_label_retained_scroll(vmap_label_collector_t * col,
761	    int32_t sx, int32_t sy, uint8_t dirty_cap, uint8_t * dirty_n,
762	    int32_t * dirty_x1, int32_t * dirty_y1,
763	    int32_t * dirty_x2, int32_t * dirty_y2)
764	{
765	    int32_t i;
766	    bool dropped;
767	
768	    if (!col || !col->retained) {
769	        return;
770	    }
771	
772	    for (i = 0; i < col->retained_count; i++) {
773	        col->retained[i].x -= sx;
774	        col->retained[i].y -= sy;
775	        col->retained[i].box.x1 -= sx;
776	        col->retained[i].box.x2 -= sx;
777	        col->retained[i].box.y1 -= sy;
778	        col->retained[i].box.y2 -= sy;
779	    }
780	
781	    if (!dirty_n || !dirty_x1 || !dirty_y1 || !dirty_x2 || !dirty_y2) {
782	        int32_t out = 0;
783	
784	        for (i = 0; i < col->retained_count; i++) {
785	            const vmap_label_retained_t * e = &col->retained[i];
786	
787	            if (e->box.x2 < 0 || e->box.y2 < 0
788	                || e->box.x1 >= col->canvas_w || e->box.y1 >= col->canvas_h) {
789	                continue;
790	            }
791	            col->retained[out++] = *e;
792	        }
793	        col->retained_count = out;
794	        return;
795	    }
796	
797	    do {
798	        int32_t out = 0;
799	
800	        dropped = false;
801	        for (i = 0; i < col->retained_count; i++) {
802	            vmap_label_retained_t e = col->retained[i];
803	            bool fully_off;
804	            bool fully_on;
805	            bool hit_dirty = false;
806	            uint8_t d;
807	
808	            fully_off = (e.box.x2 < 0 || e.box.y2 < 0
809	                || e.box.x1 >= col->canvas_w || e.box.y1 >= col->canvas_h);
810	            fully_on = (e.box.x1 >= 0 && e.box.y1 >= 0
811	                && e.box.x2 < col->canvas_w && e.box.y2 < col->canvas_h);
812	
813	            if (fully_off) {
814	                dropped = true;
815	                continue;
816	            }
817	
818	            for (d = 0; d < *dirty_n; d++) {
819	                lv_area_t dirty;
820	
821	                dirty.x1 = dirty_x1[d];
