/* ── 设备视图：240×400 实像素，与 MCU 的 z14 / scale=1 一一对应 ──
 * 桌面画布是"放大预览"，这里才是真机上 1 px 的样子：线宽、字号、
 * 无抗锯齿的边缘都在这一块里判断。
 */
const DEV_W = 240;
const DEV_H = 400;
const DEV_ZOOM = 14;

function lonToWorldPx(lon, n) {
  return (lon + 180) / 360 * n * 256;
}

function latToWorldPx(lat, n) {
  const s = Math.sin(lat * Math.PI / 180);
  return (0.5 - Math.log((1 + s) / (1 - s)) / (4 * Math.PI)) * n * 256;
}

function worldPxToLon(x, n) {
  return x / (n * 256) * 360 - 180;
}

function worldPxToLat(y, n) {
  return Math.atan(Math.sinh(Math.PI * (1 - 2 * y / (n * 256)))) * 180 / Math.PI;
}

function refreshDevicePreview() {
  const box = $("device-view");
  const canvas = $("dev-canvas");
  if (!box || !canvas || box.hidden || !state.map) return;
  const n = 2 ** DEV_ZOOM;
  const c = state.map.getCenter();
  const cx = lonToWorldPx(c.lng, n);
  const cy = latToWorldPx(c.lat, n);
  const project = (lon, lat) => [
    lonToWorldPx(lon, n) - cx + DEV_W / 2,
    latToWorldPx(lat, n) - cy + DEV_H / 2,
  ];
  const bounds = {
    getWest: () => worldPxToLon(cx - DEV_W / 2, n),
    getEast: () => worldPxToLon(cx + DEV_W / 2, n),
    getNorth: () => worldPxToLat(cy - DEV_H / 2, n),
    getSouth: () => worldPxToLat(cy + DEV_H / 2, n),
  };
  const scene = buildScene(project, bounds, { zoom: DEV_ZOOM });
  const ctx = canvas.getContext("2d");
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  VmapPainter.paint(ctx, scene, {
    style: currentStyle(),
    zoom: DEV_ZOOM,
    width: DEV_W,
    height: DEV_H,
    showLand: true,
    showLabels: true,
    showRoadNames: true,
    widthScale: 1,
    labelScale: 1,
  });
  const stat = $("dev-stat");
  if (stat) {
    stat.textContent = `${currentStyle().title} · z${DEV_ZOOM} · `
      + `${scene.road.length} 段路 / ${scene.labels.length} 标注`;
  }
}

function setDeviceView(on) {
  const box = $("device-view");
  if (!box) return;
  box.hidden = !on;
  if (on) refreshDevicePreview();
}

function refreshVec() {
  const el = $("tog-vec");
  const want = !el || el.checked;
  if (!state.map) return;
