```c
/* ── 线宽阶梯（STYLE.md §3）──────────────────────────────────────────────
 * 设备 1× 基准是 z14；style->road[cls].w 存的是 1/10 px。
 * 缩放曲线与 HTML 同一条：ws = 2^((z-14)/2) = sqrt(linear)，夹 0.62~2.4。
 * 板端的线性倍率就是瓦片 scale（z14 时 1.0），所以 ws = sqrt(scale)。
 * 每个瓦片算一次（不是每像素），sqrt 一次可忽略。
 */
static int32_t road_width_scale_q8(float scale)
{
    double ws;

    if (!(scale > 0.0f)) {
        return 256;
    }
    ws = sqrt((double)scale);
    if (ws < 0.62) ws = 0.62;
    else if (ws > 2.4) ws = 2.4;
    return (int32_t)lround(ws * 256.0);
}

static int32_t road_core_px(int32_t w10, int32_t ws_q8)
{
    int32_t px = (w10 * ws_q8 + 1280) / 2560;  /* w10/10 * ws_q8/256, 四舍五入 */
    return px < 1 ? 1 : px;
}

static int32_t road_case_px(int32_t core_px, int32_t ws_q8)
{
    int32_t ws10 = (ws_q8 * 10 + 128) >> 8;
    int32_t extra10;

    if (ws10 < 1) ws10 = 1;
    if (ws10 > 170) ws10 = 170;           /* min(1.7, ws) */
    extra10 = 19 * ws10;                  /* 1.9 * ws，单位 1/100 px */
    if (extra10 < 110) extra10 = 110;     /* max(1.1, ...) */
    return core_px + (extra10 + 50) / 100;
}
