### Dashed drawing details

I want the dash pattern to look like the reference: 5 px on, 4 off along the path. At 2px wide that's a dotted/dashed trail.

Implementation:
```c
static void draw_dashed_polyline(vmap_canvas_t *c, const vmap_point_t *pts, int32_t n, int32_t width, uint16_t color, int32_t on, int32_t off)
{
    int32_t period = on + off;
    int32_t phase = 0;
    int32_t i;

    if (period <= 0) return;
    for (i = 0; i + 1 < n; i++) {
        const int32_t ax = pts[i].x, ay = pts[i].y;
        const int32_t bx = pts[i+1].x, by = pts[i+1].y;
        const int32_t dx = bx - ax, dy = by - ay;
        int32_t len, t;

        len = (int32_t)lround(sqrt((double)dx*dx + (double)dy*dy));
        if (len <= 0) continue;
        t = 0;
        while (t < len) {
            int32_t in_phase = phase % period;
            bool in_dash = in_phase < on;
            int32_t left = in_dash ? (on - in_phase) : (period - in_phase);
            int32_t step = left > len - t ? len - t : left;

            if (in_dash && step > 0) {
                int32_t x0 = ax + (int32_t)((int64_t)dx * t / len);
                int32_t y0 = ay + (int32_t)((int64_t)dy * t / len);
                int32_t x1 = ax + (int32_t)((int64_t)dx * (t + step) / len);
                int32_t y1 = ay + (int32_t)((int64_t)dy * (t + step) / len);
                vmap_render_draw_thick_line(c, x0, y0, x1, y1, width, color);
            }
            t += step;
            phase += step;
            if (step <= 0) break;   /* 防御：on/off 为 0 时不至于死循环 */
        }
