/* ── 线宽（STYLE.md §3）─────────────────────────────────────────────────── */

/**
 * @brief 线宽倍率的定点表示（Q8）：`2^((z-14)/2)`，夹在 0.62 ~ 2.4。
 *
 * 板端的"线性倍率"就是瓦片 scale（z14 = 1×），而 zoom 每升一级线性翻倍 ⇒
 * 倍率 = sqrt(scale)，与 HTML `vmapZoomWidthScale()` 同一条曲线。每个瓦片算
 * 一次（`draw_road_layer` 入口），不是每像素 —— 热路径仍然全是整数。
 */
static int32_t road_width_scale_q8(float scale)
{
    double ws;

    if (!(scale > 0.0f)) {
        return 256;
    }

    ws = sqrt((double)scale);
    if (ws < 0.62) {
        ws = 0.62;
    } else if (ws > 2.4) {
        ws = 2.4;
    }

    return (int32_t)lround(ws * 256.0);
}

/** @brief 芯宽：1/10 px 的表值 × 倍率 ⇒ 设备像素（四舍五入，最小 1）。 */
static int32_t road_core_px(int32_t w10, int32_t ws_q8)
{
    int32_t px = (w10 * ws_q8 + 1280) / 2560;   /* w10/10 × ws_q8/256 */

    return px < 1 ? 1 : px;
}

/** @brief 壳宽 = 芯 + `max(1.1, 1.9 × min(1.7, ws))`（HTML `caseExtra` 同一式）。 */
static int32_t road_case_px(int32_t core_px, int32_t ws_q8)
{
    int32_t ws10 = (ws_q8 * 10 + 128) >> 8;
    int32_t extra;

    if (ws10 < 1) {
        ws10 = 1;
    } else if (ws10 > 170) {
        ws10 = 170;              /* min(1.7, ws) */
    }
    extra = 19 * ws10;           /* 1.9 × ws，单位 1/100 px */
    if (extra < 110) {
        extra = 110;             /* max(1.1, …) */
    }

    return core_px + (extra + 50) / 100;
}
